import{_ as t,a as i,b as r,c as o,d as s,e as a,f as n}from"./chunks/git_16.DuMhbUDR.js";import{_ as l,c as u,o as c,ag as p}from"./chunks/framework.BtwP-r-R.js";const d="/14B-POO-A26/assets/git_1.oMuGZ20s.png",g="/14B-POO-A26/assets/git_2.CDfwvAaX.png",m="/14B-POO-A26/assets/git_3.DJoP2HC_.png",f="/14B-POO-A26/assets/git_4.B_tkwSR4.png",v="/14B-POO-A26/assets/git_5.DKywNkjq.png",h="/14B-POO-A26/assets/git_6.CgJXHwH4.png",_="/14B-POO-A26/assets/git_7.DSQpFlhz.png",q="/14B-POO-A26/assets/git_8.0MllAMyz.png",b="/14B-POO-A26/assets/git_9.B9ze6_uO.png",x=JSON.parse('{"title":"Git avec Visual Studio et GitLab","description":"","frontmatter":{},"headers":[],"relativePath":"git.md","filePath":"git.md"}'),z={name:"git.md"};function j(P,e,C,G,O,A){return c(),u("div",null,[...e[0]||(e[0]=[p('<h1 id="git-avec-visual-studio-et-gitlab" tabindex="-1">Git avec Visual Studio et GitLab <a class="header-anchor" href="#git-avec-visual-studio-et-gitlab" aria-label="Permalink to &quot;Git avec Visual Studio et GitLab&quot;">​</a></h1><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Installez Git sans changer les options par défaut : <a href="http://git-scm.com/downloads" target="_blank" rel="noreferrer">http://git-scm.com/downloads</a></p><p><strong>Liens utiles</strong></p><ul><li>Documentation officielle de Git : <a href="https://git-scm.com/doc" target="_blank" rel="noreferrer">https://git-scm.com/doc</a></li><li>Cours rapide sur Git en 15 minutes : <a href="https://try.github.io/levels/1/challenges/1" target="_blank" rel="noreferrer">https://try.github.io/levels/1/challenges/1</a></li><li>Cours sur Git (niveau 1 gratuit) : <a href="http://gitreal.codeschool.com/levels/1" target="_blank" rel="noreferrer">http://gitreal.codeschool.com/levels/1</a></li><li>Cours sur Git et GitHub sur OpenClassRooms : <a href="https://openclassrooms.com/courses/gerer-son-code-avec-git-et-github" target="_blank" rel="noreferrer">https://openclassrooms.com/courses/gerer-son-code-avec-git-et-github</a></li></ul><h2 id="configuration-initiale-pour-une-equipe-travaillant-sur-un-meme-projet" tabindex="-1">Configuration initiale pour une équipe travaillant sur un même projet <a class="header-anchor" href="#configuration-initiale-pour-une-equipe-travaillant-sur-un-meme-projet" aria-label="Permalink to &quot;Configuration initiale pour une équipe travaillant sur un même projet&quot;">​</a></h2><ol><li><p><strong>Pour les deux coéquipiers</strong></p><ul><li>Créez-vous un compte sur le cloud GitLab.com (<a href="https://gitlab.com/" target="_blank" rel="noreferrer">https://gitlab.com/</a>).</li></ul></li><li><p><strong>Coéquipier 1</strong> : Celui ayant une version à jour du projet</p><ol><li>Créez-vous un nouveau projet (blank project) <strong>privé</strong> (obligatoire pour les travaux à Garneau) sur GitLab.</li></ol><p><img src="'+d+'" alt="Nouveau projet git la"></p><p><img src="'+g+'" alt="Nouveau projet git la"></p><p><img src="'+m+'" alt="Nouveau projet git la"></p><ol start="2"><li>Ajoutez votre coéquipier au projet avec le rôle « Maintainer ».</li></ol><p><img src="'+f+'" alt="Nouveau projet git la"></p><p><img src="'+v+'" alt="Nouveau projet git la"></p></li><li><p>À parti de GitLab, copiez l&#39;URL (https) du projet.</p></li></ol><p><img src="'+h+'" alt="Nouveau projet git la"></p><ol start="4"><li>Démarrez Visual Studio et sélectionnez &quot;<strong>Cloner un dépôt</strong>&quot; et copier l&#39;Url du projet sous <strong>&quot;Emplacement du dépôt&quot;</strong></li></ol><p><img src="'+_+'" alt="Nouveau projet git la"></p><p><img src="'+q+'" alt="Nouveau projet git la"></p><ol start="5"><li>Si ce n&#39;est pas déjà fait, vous aurez à configurer votre nom d&#39;utilisateur et mot de passe dans Visual Studio. N&#39;oubliez pas de cocher la case &quot;Définir dans le fichier .gitconfig global&quot;.</li></ol><p><img src="'+b+'" alt="Nouveau projet git la"></p><ol start="6"><li>Pour créer un nouveau projet, vous n&#39;avez qu&#39;à aller dans le menu Fichier et sélectionner nouveau projet. Assurez-vous que l&#39;emplacement pour la création de votre nouveau projet se trouve bien dans le même répertoire où vous avez cloné votre projet GitLab.</li></ol><h2 id="ignorer-des-fichier-gitignore" tabindex="-1">Ignorer des fichier (.gitignore) <a class="header-anchor" href="#ignorer-des-fichier-gitignore" aria-label="Permalink to &quot;Ignorer des fichier (.gitignore)&quot;">​</a></h2><p>Pour ignorer certains fichiers de votre solution afin qu&#39;ils ne soient pas publiés sur le dépôt distant et ainsi éviter des conflits, vous devez utiliser un fichier nommé « .gitignore » . Maintenant, localement sur votre ordinateur à partir de Windows, copiez le fichier</p><p>Pour ce faire, vous devez :</p><ol><li>Cliquer sur l&#39;option « <strong>…</strong> » à partir du menu « <strong>Gérer les dépôt distants …</strong> ».</li></ol><p><img src="'+t+'" alt="Nouveau projet git la"></p><ol start="2"><li>Vous devez par la suite sélectionner dans le menu, l&#39;option <strong>Paramètres du dépôt Git -&gt; Général</strong>. Dans la section, « <strong>Git files</strong> », cliquer sur le bouton « <strong>Ajouter</strong> » vis-à-vis Ingorer le fichier:</li></ol><p><img src="'+i+'" alt="Nouveau projet git la"></p><h2 id="comment-faire-pour-conserver-des-versions-de-fichier-localement" tabindex="-1">Comment faire pour conserver des versions de fichier localement? <a class="header-anchor" href="#comment-faire-pour-conserver-des-versions-de-fichier-localement" aria-label="Permalink to &quot;Comment faire pour conserver des versions de fichier localement?&quot;">​</a></h2><ul><li>À partir l&#39;onglet &quot;Modification Git&quot; <ul><li>Indiquez le texte du &quot;<strong>Commit</strong>&quot; (Celui-ci doit être significatif).</li><li>Sélectionner les fichiers à ajouter au commit.</li><li>Cliquez sur « <strong>Valider Tout</strong> ».</li></ul></li></ul><p><img src="'+r+'" alt="Nouveau projet git la"></p><h2 id="comment-faire-pour-accepter-une-version-modifiee-de-certains-fichiers-et-les-mettre-sur-le-depot-distant" tabindex="-1">Comment faire pour accepter une version modifiée de certains fichiers et les mettre sur le dépôt distant ? <a class="header-anchor" href="#comment-faire-pour-accepter-une-version-modifiee-de-certains-fichiers-et-les-mettre-sur-le-depot-distant" aria-label="Permalink to &quot;Comment faire pour accepter une version modifiée de certains fichiers et les mettre sur le dépôt distant ?&quot;">​</a></h2><p>Important : Avant de pouvoir effectuer un « <strong>Push</strong> », vous devez avoir une copie à jour des fichiers du dépôt distant. Ainsi, il est préférable, ***voire nécessaire, de **toujours faire un « Pull » avant un « Push »**s.</p><ul><li>Exécutez les commandes suivantes dans cet ordre : <ul><li>À partir de l&#39;onglet « Modification Git», saisissez le texte du &quot;Commit&quot; (celui-ci doit être significatif) et cliquez sur « <strong>Valider tout et synchroniser</strong> ».</li><li>Éventuellement, vous devrez gérer manuellement les conflits si la version locale d’un fichier est différente de celle sur le dépôt distant.</li><li>S’il n’y a aucun conflit, alors cliquez sur le lien « <strong>Pousser</strong> ».</li></ul></li></ul><h2 id="comment-resoudre-des-conflits" tabindex="-1">Comment résoudre des conflits <a class="header-anchor" href="#comment-resoudre-des-conflits" aria-label="Permalink to &quot;Comment résoudre des conflits&quot;">​</a></h2><p>Lorsque vous tentez de pousser vos modifications sur le dépôt distant, il se peut que le message suivant s&#39;affiche :</p><p><img src="'+o+'" alt="Message de conflit"></p><p>Cela indique que votre version du code n&#39;est pas à jour par rapport à celle se trouvant sur le dépôt distant. <strong>Vous devez donc synchroniser votre code en tirant celui qui se trouve sur le dépôt distant</strong>.</p><p>Lors d’une synchronisation, il se peut que vous ayez des conflits à résoudre avant de pouvoir pousser votre code :</p><p><img src="'+s+'" alt="Message de conflit"></p><p>Dans ce cas, cliquez sur le lien « <strong>Ouvrir l&#39;éditeur de fusion</strong> ». La fenêtre suivante affichera les conflits :</p><p><img src="'+a+'" alt="Message de conflit"></p><p>Vous n’aurez qu’à cocher le code du côté distant ou local que vous désirez conserver et celui-ci apparaîtra dans la section du bas. Une fois terminé, cliquez sur le bouton « <strong>Accepter la fusion</strong> ».</p><p><img src="'+n+'" alt="Message de conflit"></p><p>À partir de la fenêtre « <strong>Modifications Git</strong> », saisissez le texte du &quot;Commit&quot; (celui-ci doit être significatif) et cliquez sur « <strong>Valider les changements pousser</strong>».</p>',38)])])}const S=l(z,[["render",j]]);export{x as __pageData,S as default};
